/** The core catalog this runtime carries, for the import bdd-suite:core. */
export const CORE_CATALOG = "# The core actions: the ones every runtime implements and every workspace can\n# use without declaring them. A workspace catalog imports this file and adds\n# its own actions (DEC-S10):\n#\n#   imports:\n#     - <path to this repository>/spec/core.catalog.yaml\n#\n# A validator reads the merged catalog for E104 (unknown action), E105 (unknown\n# parameter), E201 (action the selected binding does not implement) and E302 (a\n# path absent from a capture shape); Build-Schema.ps1 folds it into the\n# workspace's suite.schema.json so an editor offers the same parameters.\n#\n# A capture shape that sets additionalProperties: true is open, and a path into\n# it is not checked.\ncatalogVersion: 1\nbindings: [powershell, csharp, go, rust, typescript]\n\nactions:\n  - name: core.noop\n    summary: Do nothing and return that it happened.\n    bindings: [powershell, csharp, go, rust, typescript]\n    interruptible: true\n    notes: >-\n      What a then step uses when its whole job is to carry a sentence and assert\n      on what earlier steps already captured.\n    captures:\n      type: object\n      additionalProperties: false\n      properties:\n        ok: { type: boolean }\n\n  - name: core.set\n    summary: Publish a literal value under captureAs.\n    bindings: [powershell, csharp, go, rust, typescript]\n    interruptible: true\n    params:\n      - { name: value, type: any, required: true }\n    captures:\n      type: any\n      description: Whatever value the step declared.\n\n  - name: core.fail\n    summary: Fail on purpose with a chosen message.\n    bindings: [powershell, csharp, go, rust, typescript]\n    interruptible: true\n    params:\n      - { name: message, type: string, default: 'core.fail: failed on purpose' }\n    captures:\n      type: any\n      description: Nothing; the step always fails.\n\n  - name: core.sleep\n    summary: Sleep for a number of seconds, interruptibly.\n    bindings: [powershell, csharp, go, rust, typescript]\n    interruptible: true\n    params:\n      - { name: seconds, type: number, default: 1 }\n    captures:\n      type: object\n      additionalProperties: false\n      properties:\n        sleptSec: { type: number }\n\n  - name: core.record\n    summary: Append one marker to the run trace, so a phase order can be asserted.\n    bindings: [powershell, csharp, go, rust, typescript]\n    interruptible: true\n    notes: >-\n      The trace file is named by the runtime's record environment variable (BDD_SUITE_RECORD_PATH by default).\n      Without it the marker is only returned.\n    params:\n      - { name: marker, type: string, required: true }\n    captures:\n      type: object\n      additionalProperties: false\n      properties:\n        marker: { type: string }\n\n  - name: wait\n    summary: Sleep for a number of seconds, or poll a step until a condition holds.\n    bindings: [powershell, csharp, go, rust, typescript]\n    interruptible: true\n    notes: >-\n      The poll is bounded by the step's own timeoutSec, which every step carries\n      since Y2.3, so this action declares no limit of its own. The poll loop\n      itself is interruptible; a forStep whose action is not is only as\n      cancellable as that action, which is why the nested step carries its own\n      entry in this catalog.\n    params:\n      - { name: seconds, type: integer, description: Sleep this long and return. Ignored when forStep is present. }\n      - { name: forStep, type: object, ref: step, description: The step to run on every poll. }\n      - { name: until, type: object, ref: assert, description: The condition that ends the poll successfully. }\n      - { name: intervalSec, type: integer, default: 10, description: Seconds between polls. }\n    captures:\n      type: object\n      additionalProperties: false\n      properties:\n        waitedSec: { type: integer, description: Present for a plain sleep. }\n        waited: { type: boolean, description: Present when a poll condition was met. }\n        elapsedSec: { type: integer, description: Present when a poll condition was met. }\n\n";
